package com.internhub.service;
import java.util.List;
import com.internhub.dto.*; import com.internhub.entity.*; import com.internhub.exception.ResourceNotFoundException; import com.internhub.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class ProfileService { private final UserRepository users; private final StudentProfileRepository students; private final CompanyProfileRepository companies; private final InternshipRepository internships; private final ApplicationRepository applications;
 public ProfileService(UserRepository u,StudentProfileRepository s,CompanyProfileRepository c,InternshipRepository i,ApplicationRepository a){users=u;students=s;companies=c;internships=i;applications=a;}
 private User user(Long id){return users.findById(id).orElseThrow(()->new ResourceNotFoundException("User not found."));}
 @Transactional(readOnly=true) public ProfileResponses.Student student(Long id){var p=students.findByUserId(id).orElseThrow(()->new ResourceNotFoundException("Student profile not found."));return new ProfileResponses.Student(com.internhub.dto.UserSummary.from(p.getUser()),p.getPhone(),p.getInstitution(),p.getDegreeOrBranch(),p.getGraduationYear(),p.getCgpa(),List.copyOf(p.getSkills()));}
 @Transactional public ProfileResponses.Student updateStudent(Long id,StudentProfileRequest r){var u=user(id);var p=students.findByUserId(id).orElseThrow(()->new ResourceNotFoundException("Student profile not found."));u.setFullName(r.name().trim());p.setPhone(r.phone());p.setInstitution(r.institution());p.setDegreeOrBranch(r.degreeOrBranch());p.setGraduationYear(r.graduationYear());p.setCgpa(r.cgpa());p.getSkills().clear();if(r.skills()!=null)p.getSkills().addAll(r.skills().stream().filter(s->s!=null&&!s.isBlank()).map(String::trim).distinct().toList());return student(id);}
 @Transactional(readOnly=true) public ProfileResponses.Company company(Long id){var p=companies.findByUserId(id).orElseThrow(()->new ResourceNotFoundException("Company profile not found."));return new ProfileResponses.Company(com.internhub.dto.UserSummary.from(p.getUser()),p.getCompanyName(),p.getDescription(),p.getWebsite(),p.getIndustry(),p.getContactInformation());}
 @Transactional public ProfileResponses.Company updateCompany(Long id,CompanyProfileRequest r){var p=companies.findByUserId(id).orElseThrow(()->new ResourceNotFoundException("Company profile not found."));p.setCompanyName(r.companyName().trim());p.setDescription(r.description());p.setWebsite(r.website());p.setIndustry(r.industry());p.setContactInformation(r.contactInformation());return company(id);}
 @Transactional(readOnly=true) public ProfileResponses.Dashboard studentDashboard(Long id){var p=students.findByUserId(id).orElseThrow(()->new ResourceNotFoundException("Student profile not found."));return new ProfileResponses.Dashboard(applications.findByStudentId(p.getId(),org.springframework.data.domain.PageRequest.of(0,1)).getTotalElements(),internships.countByStatus(InternshipStatus.OPEN),0);}
 @Transactional(readOnly=true) public ProfileResponses.Dashboard companyDashboard(Long id){var p=companies.findByUserId(id).orElseThrow(()->new ResourceNotFoundException("Company profile not found."));return new ProfileResponses.Dashboard(0,internships.findByCompanyId(p.getId(),org.springframework.data.domain.PageRequest.of(0,1)).getTotalElements(),applications.countByInternshipCompanyId(p.getId()));}
}
